#include "stdlib/lapack/base/dlassq.h"
#include <math.h>

#define SBIG 1.11137937474253874e-162
#define SSML 4.49891379454319638e+161
#define TBIG 1.99791907220223503e+146
#define TSML 1.49166814624004135e-154

/**
* Returns an updated sum of squares represented in scaled form using alternative indexing semantics.
*
* @param N        number of indexed elements
* @param X        input array
* @param strideX  stride length for `X`
* @param offsetX  starting index for `X`
* @param scale    scaling factor
* @param sumsq    basic sum of squares from which output is factored out
*/
void API_SUFFIX(c_dlassq_ndarray)( const LAPACK_INT N, const double *X, const LAPACK_INT strideX, const LAPACK_INT offsetX, double *scale, double *sumsq ) {
	int notbig;
	double abig;
	double asml;
	double amed;
	double ymin;
	double ymax;
	double ax;
	double tmp;
	LAPACK_INT ox;
	LAPACK_INT i;

	if ( isnan( *scale ) || isnan( *sumsq ) ) {
		return;
	}
	if ( *sumsq == 0.0 ) {
		*scale = 1.0;
	}
	if ( *scale == 0.0 ) {
		*scale = 1.0;
		*sumsq = 0.0;
	}
	if ( N <= 0 ) {
		return;
	}

	notbig = 1;
	asml = 0.0;
	amed = 0.0;
	abig = 0.0;
	ox = offsetX;

	for ( i = 0; i < N; i++ ) {
		ax = fabs( X[ ox ] );
		if ( ax > TBIG ) {
			tmp = ax * SBIG;
			abig += ( tmp * tmp );
			notbig = 0;
		} else if ( ax < TSML ) {
			if ( notbig ) {
				tmp = ax * SSML;
				asml += ( tmp * tmp );
			}
		} else {
			amed += ( ax * ax );
		}
		ox += strideX;
	}

	if ( *sumsq > 0.0 ) {
		ax = *scale * sqrt( *sumsq );
		if ( ax > TBIG ) {
			if ( *scale > 1.0 ) {
				*scale *= SBIG;
				abig += *scale * ( *scale * ( *sumsq ) );
			} else {
				abig += *scale * ( *scale * ( SBIG * ( SBIG * ( *sumsq ) ) ) );
			}
		} else if ( ax < TSML ) {
			if ( notbig ) {
				if ( *scale < 1.0 ) {
					*scale *= SSML;
					asml += *scale * ( *scale * ( *sumsq ) );
				} else {
					asml += *scale * ( *scale * ( SSML * ( SSML * ( *sumsq ) ) ) );
				}
			}
		} else {
			amed += *scale * ( *scale * ( *sumsq ) );
		}
	}

	if ( abig > 0.0 ) {
		if ( amed > 0.0 || isnan( amed ) ) {
			abig += ( amed * SBIG ) * SBIG;
		}
		*scale = 1.0 / SBIG;
		*sumsq = abig;
		return;
	}

	if ( asml > 0.0 ) {
		if ( amed > 0.0 || isnan( amed ) ) {
			amed = sqrt( amed );
			asml = sqrt( asml ) / SSML;
			if ( asml > amed ) {
				ymin = amed;
				ymax = asml;
			} else {
				ymin = asml;
				ymax = amed;
			}
			*scale = 1.0;
			tmp = ymin / ymax;
			*sumsq = ( ymax * ymax ) * ( 1.0 + ( tmp * tmp ) );
		} else {
			*scale = 1.0 / SSML;
			*sumsq = asml;
		}
		return;
	}

	*scale = 1.0;
	*sumsq = amed;
	return;
}
